void push_front(struct Node **head, int v) {
  struct Node *n = malloc(sizeof *n);
  n->data = v; n->next = *head; *head = n;
}

void delete_value(struct Node **head, int v) {
  for (struct Node **pp = head; *pp; pp = &(*pp)->next)
    if ((*pp)->data == v) { struct Node *t = *pp; *pp = t->next; free(t); return; }
}

struct Node *prev = NULL, *cur = head;
while (cur) { struct Node *nx = cur->next; cur->next = prev; prev = cur; cur = nx; }
head = prev;
